/**
 * THE ECO-AGENT PROTOCOL (EAP) - CORE ARCHIPELAGO STATE ENGINE
 * * This is a stateless-friendly, pure logic simulator designed for rapid prototyping.
 * It manages the thermodynamics of thought:
 * - Layer 1: Physical constraints (Sunlight/Tokens, Context Window, AST Nutrients)
 * - Layer 2/3: Worker Current (Specialized disposable boats doing manual execution)
 * - Layer 4: The Narrative Ledger (Lighthouses compressing telemetry into stories)
 * - Layer 5: The Helm (Sovereign human intervention via Nudges)
 */

class ArchipelagoEngine {
  constructor(config = {}) {
    this.config = {
      initialSunlight: config.initialSunlight || 1000,
      initialAttention: config.initialAttention || 3,
      gridWidth: config.gridWidth || 10,
      gridHeight: config.gridHeight || 10,
      decayThreshold: config.decayThreshold || 100,
      ...config
    };

    this.reset();
  }

  /**
   * Resets the entire ecosystem state to its pristine, unpolluted baseline.
   */
  reset() {
    this.state = {
      turn: 1,
      resources: {
        sunlight: this.config.initialSunlight, // Total API token budget
        astNutrients: 100,                     // Library of pre-decomposed code primitives
        decay: 10,                             // Software rot/chaos percentage (0-100)
        integration: 0                         // Global project completion progress (0-100)
      },
      attention: {
        current: this.config.initialAttention,
        max: this.config.initialAttention
      },
      // Layer 4 &amp; Part of 3: The Stationary Narrators
      lighthouses: [
        { id: &quot;core_arch&quot;, name: &quot;Core Architecture&quot;, col: 2, row: 2, focus: &quot;Idle&quot;, scaffolding: 0, crystallized: 0, progress: 10 },
        { id: &quot;media_ingest&quot;, name: &quot;Media Ingestion&quot;, col: 7, row: 2, focus: &quot;Idle&quot;, scaffolding: 0, crystallized: 0, progress: 0 },
        { id: &quot;ui_framework&quot;, name: &quot;UI &amp; Presentation&quot;, col: 2, row: 7, focus: &quot;Idle&quot;, scaffolding: 0, crystallized: 0, progress: 0 },
        { id: &quot;knowledge_base&quot;, name: &quot;Semantic Memory&quot;, col: 7, row: 7, focus: &quot;Idle&quot;, scaffolding: 0, crystallized: 0, progress: 0 }
      ],
      // Layer 2 &amp; Part of 3: The Disposable Workforce Fleet
      boats: [],
      // Layer 4: The Mapmaker
      chronicle: []
    };

    this.logEvent(&quot;Sovereign Bridge Anchored&quot;, &quot;Physical riverbed initialized. The lighthouses are standing ready to direct the flow.&quot;);
  }

  /**
   * Layer 5 -&gt; Layer 4: The Human Operator inputs guidance (&quot;The Nudge&quot;).
   * This updates the lighthouse&#39;s internal story mode.
   * @param {string} lighthouseId - The target narrator island
   * @param {string} focusType - &quot;Exploration&quot; (Wild Child), &quot;Pruning&quot; (Gardener), &quot;Integration&quot; (Tugboat), or &quot;Idle&quot;
   */
  nudge(lighthouseId, focusType) {
    const lighthouse = this.state.lighthouses.find(l =&gt; l.id === lighthouseId);
    if (!lighthouse) return false;

    if (this.state.attention.current &lt; 1) {
      this.logEvent(&quot;Attention Depleted&quot;, `Operator attempted to steer ${lighthouse.name} to [${focusType}] but lacked high-level Attention energy.`);
      return false;
    }

    this.state.attention.current -= 1;
    const oldFocus = lighthouse.focus;
    lighthouse.focus = focusType;

    this.logEvent(
      &quot;Sovereign Nudge Applied&quot;,
      `Narrator [${lighthouse.name}] shifted internal story from [${oldFocus}] to [${focusType}].`
    );

    // Dynamic down-regulation action cascading
    if (focusType === &quot;Exploration&quot;) {
      this.spawnBoat(lighthouseId, &quot;icebreaker&quot;);
    } else if (focusType === &quot;Pruning&quot;) {
      this.spawnBoat(lighthouseId, &quot;dredger&quot;);
    } else if (focusType === &quot;Integration&quot;) {
      this.spawnBoat(lighthouseId, &quot;tugboat&quot;);
    }

    this.calculateIntegration();
    return true;
  }

  /**
   * Layer 4 -&gt; Layer 2: Narrator spawns a specialized boat hull in its territory.
   */
  spawnBoat(lighthouseId, type) {
    const lighthouse = this.state.lighthouses.find(l =&gt; l.id === lighthouseId);
    if (!lighthouse) return null;

    // Boats spawn close to their parent lighthouse
    const colOffset = Math.floor(Math.random() * 3) - 1;
    const rowOffset = Math.floor(Math.random() * 3) - 1;

    const boat = {
      id: `boat_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
      type, // &quot;icebreaker&quot;, &quot;dredger&quot;, &quot;tugboat&quot;
      lighthouseId,
      col: Math.min(this.config.gridWidth - 1, Math.max(0, lighthouse.col + colOffset)),
      row: Math.min(this.config.gridHeight - 1, Math.max(0, lighthouse.row + rowOffset)),
      fuel: 100 // Local lifetime of active context
    };

    this.state.boats.push(boat);
    this.logEvent(&quot;Worker Dispatched&quot;, `A specialized ${type.toUpperCase()} boat has been deployed by the [${lighthouse.name}] lighthouse beam.`);
    return boat;
  }

  /**
   * Ruthless Ephemerality: The down-regulation wipe command.
   * Completely liquidates a lighthouse&#39;s workforce and reverts its scaffolding.
   * No technical debt survives this command.
   */
  flashFreeze(lighthouseId) {
    const lighthouse = this.state.lighthouses.find(l =&gt; l.id === lighthouseId);
    if (!lighthouse) return;

    this.logEvent(&quot;Wipe Sequence Triggered&quot;, `FLASH FREEZE initiated for [${lighthouse.name}] core workspace.`);

    // 1. Terminate all active boats assigned to this lighthouse
    const activeBoatsCount = this.state.boats.filter(b =&gt; b.lighthouseId === lighthouseId).length;
    this.state.boats = this.state.boats.filter(b =&gt; b.lighthouseId !== lighthouseId);

    // 2. Composing scaffolding (Layer 1 salvage)
    const salvagedNutrients = lighthouse.scaffolding * 5;
    const sunlightRefunded = activeBoatsCount * 25;

    this.state.resources.astNutrients += salvagedNutrients;
    this.state.resources.sunlight += sunlightRefunded;

    // 3. Reset internal structures
    lighthouse.scaffolding = 0;
    lighthouse.crystallized = 0;
    lighthouse.focus = &quot;Idle&quot;;

    this.logEvent(
      &quot;Compost Cycle Complete&quot;,
      `Workspace cleaned. Salvaged +${salvagedNutrients} AST Nutrients to Soil. Refunded +${sunlightRefunded} Sunlight tokens. Zero code pollution remains.`
    );

    this.calculateIntegration();
  }

  /**
   * Advances the entire fluid engine forward by 1 Week (Tick).
   * Calculates physics, resource burns, generation, and updates the Chronicle.
   */
  tick() {
    this.state.turn += 1;
    this.state.attention.current = this.state.attention.max; // Replenish human energy

    let globalBurn = 0;
    let totalScaffolding = 0;
    const achievements = [];

    // 1. Process active Workers (Layer 2 &amp; 3 currents)
    this.state.boats.forEach(boat =&gt; {
      // Burn logic
      let boatBurn = 5;
      if (boat.type === &quot;icebreaker&quot;) boatBurn = 15;
      if (boat.type === &quot;dredger&quot;) boatBurn = 10;
      globalBurn += boatBurn;

      // Simulate localized movement inside the shipping channels
      const move = Math.random() &gt; 0.5 ? 1 : -1;
      if (Math.random() &gt; 0.5) {
        boat.col = Math.min(this.config.gridWidth - 1, Math.max(0, boat.col + move));
      } else {
        boat.row = Math.min(this.config.gridHeight - 1, Math.max(0, boat.row + move));
      }

      boat.fuel -= 15; // Deplete local context window limit
    });

    // Clean up out-of-fuel (exhausted context) boats
    const originalCount = this.state.boats.length;
    this.state.boats = this.state.boats.filter(b =&gt; b.fuel &gt; 0);
    const expiredCount = originalCount - this.state.boats.length;
    if (expiredCount &gt; 0) {
      this.logEvent(&quot;Context Expired&quot;, `${expiredCount} worker boats dissolved as their context windows reached saturation limits.`);
    }

    // 2. Process active Narrator Lighthouses &amp; apply local domain strategies
    this.state.lighthouses.forEach(lighthouse =&gt; {
      if (lighthouse.focus === &quot;Exploration&quot;) {
        // High risk, high speed exploration (Wild Child phase)
        lighthouse.scaffolding += 3;
        lighthouse.progress = Math.min(100, lighthouse.progress + 4);
        globalBurn += 10; // Extra computing overhead
      } else if (lighthouse.focus === &quot;Pruning&quot;) {
        // Shaving abstractions down to crystalline structures (Gardener phase)
        if (lighthouse.scaffolding &gt; 0) {
          const cut = Math.min(lighthouse.scaffolding, 3);
          lighthouse.scaffolding -= cut;
          lighthouse.crystallized += Math.max(1, Math.floor(cut / 1.5));
          achievements.push(`${lighthouse.name} crystallized scaffolding into pure functional logic.`);
        } else {
          // No scaffolding - shift to idle automatically to conserve resources
          lighthouse.focus = &quot;Idle&quot;;
        }
      } else if (lighthouse.focus === &quot;Integration&quot;) {
        // Pouring solid primitives into system progress (Tugboat phase)
        if (lighthouse.crystallized &gt; 0) {
          lighthouse.crystallized -= 1;
          lighthouse.progress = Math.min(100, lighthouse.progress + 12);
          achievements.push(`${lighthouse.name} anchored crystalline primitives into main line.`);
        } else {
          lighthouse.focus = &quot;Idle&quot;;
        }
      }

      totalScaffolding += lighthouse.scaffolding;
    });

    // 3. Apply Soil/Riverbed Physical Laws (Layer 1 limits)
    this.state.resources.sunlight = Math.max(0, this.state.resources.sunlight - globalBurn);

    // Chaos/Rot accumulates based on total unpruned scaffolding (technical debt)
    const decayPressure = totalScaffolding * 1.5;
    if (decayPressure &gt; 5) {
      this.state.resources.decay = Math.min(100, this.state.resources.decay + Math.floor(decayPressure - 2));
    } else {
      this.state.resources.decay = Math.max(5, this.state.resources.decay - 2); // Natural stabilization
    }

    // 4. Up-Regulation: Compile weekly narrative summary
    this.compileWeeklyChronicle(globalBurn, totalScaffolding, achievements);
    this.calculateIntegration();
  }

  /**
   * Translates millions of tiny chaotic details into a readable high-level story.
   */
  compileWeeklyChronicle(burn, scaffolding, achievements) {
    const lines = [
      `System burn rate: -${burn} Sunlight tokens. Ambient technical debt in environment: ${scaffolding} modular blocks.`
    ];

    if (achievements.length &gt; 0) {
      lines.push(...achievements);
    } else if (this.state.boats.length === 0) {
      lines.push(&quot;The archipelago is quiet. No active currents or workforce detected in the shipping lanes.&quot;);
    }

    if (this.state.resources.decay &gt; 60) {
      lines.push(&quot;WARNING: High level of unpruned software decay detected! Refactor active areas to prevent system gridlock.&quot;);
    }

    this.logEvent(`Chronicle Ledger - Week ${this.state.turn - 1} Report`, lines.join(&quot; | &quot;));
  }

  calculateIntegration() {
    let sum = 0;
    this.state.lighthouses.forEach(l =&gt; sum += l.progress);
    this.state.resources.integration = Math.min(100, Math.floor(sum / this.state.lighthouses.length));
  }

  logEvent(title, detail) {
    this.state.chronicle.unshift({
      turn: this.state.turn,
      time: new Date().toLocaleTimeString([], { hour: &#39;2-digit&#39;, minute: &#39;2-digit&#39;, second: &#39;2-digit&#39; }),
      title,
      detail
    });
  }

  /**
   * Clean console visualization of the entire state machine.
   */
  getTelemetry() {
    return {
      turn: this.state.turn,
      resources: { ...this.state.resources },
      attention: { ...this.state.attention },
      boatsActive: this.state.boats.length,
      islandStates: this.state.lighthouses.map(l =&gt; ({
        id: l.id,
        name: l.name,
        strategy: l.focus,
        scaffolding: l.scaffolding,
        crystals: l.crystallized,
        progress: `${l.progress}%`
      }))
    };
  }
}

